def apply(rel, txt):
    if rel not in HUNKS:
        raise SystemExit('ashira_538: no hunk on ' + rel)
    for old, new in HUNKS[rel]:
        n = txt.count(old)
        if n != 1:
            raise SystemExit('ashira_538: anchor x%d in the live %s: %r' % (n, rel, old.strip()[:70]))
        txt = txt.replace(old, new)
    return txt
